package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Capability/status inspection only. Backup, optimize and rebuild remain disabled. */
public final class UserManagerMaintenanceActivity extends Activity {private TextView status,out;private final ExecutorService worker=Executors.newSingleThreadExecutor();@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(18,20,18,28);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);TextView t=new TextView(this);t.setText("صيانة User Manager");t.setTextSize(24);t.setTextColor(Color.rgb(22,47,80));p.addView(t);status=txt("قراءة القدرة...",14);p.addView(status);out=txt("",14);p.addView(out);Button b=new Button(this);b.setText("إعادة اكتشاف الحالة");b.setOnClickListener(v->load());p.addView(b);load();}private void load(){worker.execute(()->{try{android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pw=new SecureConnectionStore(this).get();try(RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false))){r.login(p.getString("user",""),pw==null?"":pw);List<Map<String,String>> x=r.execute("/system/resource/print","=.proplist=version,board-name");String v=x.isEmpty()?"":x.get(0).getOrDefault("version","");String root=v.startsWith("6.")?"/tool/user-manager":"/user-manager";List<Map<String,String>> users=new UserManagerService(r).users(v);String msg="RouterOS: "+v+"\nالمسار: "+root+"\nالمستخدمون: "+users.size()+"\n\nالنسخ الاحتياطي والصيانة المتقدمة معطلة حتى اعتماد خطة تراجع واختبار ميداني.";ui(()->{status.setText("تم الفحص القراءة فقط");out.setText(msg);});}}catch(Exception e){ui(()->{status.setText("غير متاح");out.setText(e.getMessage()==null?"الحزمة غير مثبتة أو لا توجد صلاحية":e.getMessage());});}});}private TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(22,47,80));t.setPadding(8,10,8,10);return t;}private void ui(Runnable r){runOnUiThread(r);}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}}
